import { Fragment, type ReactNode } from "react";
import { safeHref, cleanBareUrl } from "@shared/utils/links";

/**
 * Minimal, dependency-free markdown renderer covering the basics used in
 * research posts: headings, lists, blockquotes, bold/italic/inline-code,
 * explicit + bare links, colored text, and paragraphs.
 */

// Curated color spans (`{c:key}text{/c}`) - generated by PostEditor's color
// toolbar buttons, not meant to be hand-typed. Kept to the site's existing
// design tokens rather than allowing arbitrary CSS/inline styles.
// Root-relative links point back into this site, so they should navigate in
// place. Forcing target="_blank" on them spawned a tab every time a member
// followed a citation inside the XYZ AI panel. External links still open in a
// new tab (with the usual rel guard).
function linkTarget(href: string): { target?: string; rel?: string } {
  return href.startsWith("/") || href.startsWith("#")
    ? {}
    : { target: "_blank", rel: "noopener noreferrer" };
}

const COLOR_CLASS: Record<string, string> = {
  gold: "text-gold-300",
  mint: "text-mint-300",
  red: "text-rose-400",
  blue: "text-sky-400",
};
const COLOR_TAG = /\{c:(gold|mint|red|blue)\}([\s\S]*?)\{\/c\}/;

function inline(text: string, keyBase: string): ReactNode[] {
  const tokens: ReactNode[] = [];
  // [text](url) is matched before bare URLs so it wins; then bare http(s) links.
  // Bold's closing "**" requires a negative lookahead for a further "*" - without
  // it, overlapping bold+italic (e.g. "**hello *world***", from bolding then
  // italicizing part of the same run) stops at the FIRST "**" it finds, which
  // lands mid-run and drops the bold wrapper / leaks stray "*" characters as
  // visible text on the published post. The lookahead makes it prefer the "**"
  // that isn't immediately followed by another star, so "***" tails resolve as
  // "closing italic then bold" instead of "closing bold one star short."
  const regex = /(\{c:(?:gold|mint|red|blue)\}[\s\S]*?\{\/c\}|\*\*[\s\S]+?\*\*(?!\*)|\*[^*]+\*|`[^`]+`|\[[^\]]+\]\([^)]+\)|https?:\/\/[^\s<]+)/g;
  let last = 0;
  let match: RegExpExecArray | null;
  let i = 0;
  while ((match = regex.exec(text))) {
    if (match.index > last) tokens.push(text.slice(last, match.index));
    const t = match[0];
    const key = `${keyBase}-${i++}`;
    if (t.startsWith("{c:")) {
      const m = COLOR_TAG.exec(t);
      if (m) tokens.push(<span key={key} className={COLOR_CLASS[m[1]]}>{inline(m[2], key)}</span>);
    } else if (t.startsWith("**")) tokens.push(<strong key={key}>{inline(t.slice(2, -2), key)}</strong>);
    else if (t.startsWith("`")) tokens.push(<code key={key}>{t.slice(1, -1)}</code>);
    else if (t.startsWith("[")) {
      const m = /\[([^\]]+)\]\(([^)]+)\)/.exec(t);
      if (m) {
        const href = safeHref(m[2]);
        tokens.push(
          href ? (
            <a key={key} href={href} {...linkTarget(href)}>{inline(m[1], key)}</a>
          ) : (
            <span key={key}>{inline(m[1], key)}</span>
          )
        );
      }
    } else if (t.startsWith("http")) {
      // Bare pasted URL → clickable; trailing punctuation kept as plain text.
      const url = cleanBareUrl(t);
      const trailing = t.slice(url.length);
      const href = safeHref(url);
      tokens.push(
        href ? (
          <a key={key} href={href} {...linkTarget(href)}>{url}</a>
        ) : (
          <span key={key}>{url}</span>
        )
      );
      if (trailing) tokens.push(trailing);
    } else if (t.startsWith("*")) tokens.push(<em key={key}>{inline(t.slice(1, -1), key)}</em>);
    last = match.index + t.length;
  }
  if (last < text.length) tokens.push(text.slice(last));
  return tokens;
}

/** `| a | b |` - a row is any line whose first non-space character is a pipe. */
const isTableRow = (s: string) => s.trim().startsWith("|");

/** The cells of one row, without the outer pipes. */
const tableCells = (s: string) =>
  s.trim().replace(/^\|/, "").replace(/\|$/, "").split("|").map((c) => c.trim());

/**
 * `| --- | :---: |` - the row that makes a table a table.
 *
 * Every cell must be dashes (with optional alignment colons). Requiring it is
 * what keeps an ordinary sentence containing a pipe from being swallowed as a
 * one-row table.
 */
const isTableSeparator = (s: string) => {
  if (!isTableRow(s)) return false;
  const cells = tableCells(s);
  return cells.length > 0 && cells.every((c) => /^:?-{2,}:?$/.test(c));
};

export function Markdown({ content }: { content: string }) {
  const lines = content.replace(/\r\n/g, "\n").split("\n");
  const blocks: ReactNode[] = [];
  let list: string[] = [];
  let key = 0;

  const flushList = () => {
    if (list.length) {
      const items = [...list];
      blocks.push(
        <ul key={`ul-${key++}`}>
          {items.map((it, idx) => (
            <li key={idx}>{inline(it, `li-${key}-${idx}`)}</li>
          ))}
        </ul>
      );
      list = [];
    }
  };

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i]!.trimEnd();
    if (/^\s*[-*]\s+/.test(line)) {
      list.push(line.replace(/^\s*[-*]\s+/, ""));
      continue;
    }
    flushList();
    if (!line.trim()) continue;

    // ⚠️ Tables. The XYZ AI system prompt asks the model for "tables when
    // comparing", and globals.css has carried `.prose-xyz table/th/td` styling
    // for both themes all along - but nothing here ever produced a <table>, so
    // a comparison answer ("BTC vs ETH") fell through to the paragraph branch
    // and rendered as a wall of literal `|` and `|---|---|` in the chat panel
    // and in any research post that tried one.
    //
    // A table is a header row, a separator row of dashes, then body rows. The
    // separator is what distinguishes it from a paragraph that merely contains
    // a pipe, so it is required rather than optional.
    if (isTableRow(line) && i + 1 < lines.length && isTableSeparator(lines[i + 1]!)) {
      const head = tableCells(line);
      const body: string[][] = [];
      let j = i + 2;
      while (j < lines.length && isTableRow(lines[j]!)) {
        body.push(tableCells(lines[j]!));
        j++;
      }
      const k = key++;
      blocks.push(
        // Its own scroll container: the AI panel is narrow and a four-column
        // comparison would otherwise push the whole page sideways, which
        // CLAUDE.md calls out as never acceptable.
        <div key={`tw-${k}`} className="my-4 overflow-x-auto">
          <table>
            <thead>
              <tr>{head.map((c, ci) => <th key={ci}>{inline(c, `th-${k}-${ci}`)}</th>)}</tr>
            </thead>
            <tbody>
              {body.map((row, ri) => (
                <tr key={ri}>
                  {/* Pad short rows to the header width so a ragged table from
                      a model that dropped a cell still lines up. */}
                  {head.map((_, ci) => <td key={ci}>{inline(row[ci] ?? "", `td-${k}-${ri}-${ci}`)}</td>)}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      );
      i = j - 1;
      continue;
    }
    if (line.startsWith("### ")) blocks.push(<h3 key={key++}>{inline(line.slice(4), `h3-${key}`)}</h3>);
    else if (line.startsWith("## ")) blocks.push(<h2 key={key++}>{inline(line.slice(3), `h2-${key}`)}</h2>);
    else if (line.startsWith("# ")) blocks.push(<h1 key={key++}>{inline(line.slice(2), `h1-${key}`)}</h1>);
    else if (line.startsWith("> ")) blocks.push(<blockquote key={key++}>{inline(line.slice(2), `bq-${key}`)}</blockquote>);
    else blocks.push(<p key={key++}>{inline(line, `p-${key}`)}</p>);
  }
  flushList();

  return <Fragment>{blocks}</Fragment>;
}
